package br.com.onda;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;

@androidx.media3.common.util.UnstableApi
public class YouTubeFavoritesActivity extends Activity {
 private final List<YouTubeFavoritesData.Item> shown=new ArrayList<>();private EditText search;private TextView status;private ListView list;private BaseAdapter adapter;private AlertDialog optionsDialog,editDialog;private boolean opening;
 @Override protected void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar dos favoritos do YouTube");header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),-2));header.addView(Ui.text(this,"Favoritos do YouTube",21,Ui.TEXT),new LinearLayout.LayoutParams(0,-2,1));root.addView(header);search=new EditText(this);Ui.input(search);search.setSingleLine(true);search.setHint("Buscar nos favoritos");search.setContentDescription("Buscar favoritos do YouTube");search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(160)});root.addView(search);status=Ui.text(this,"",13,Ui.MUTED);status.setPadding(0,Ui.dp(this,8),0,Ui.dp(this,8));root.addView(status);list=new ListView(this);list.setContentDescription("Lista de favoritos do YouTube");list.setDivider(null);adapter=new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int i){return shown.get(i);}public long getItemId(int i){return i;}public View getView(int i,View recycled,ViewGroup parent){LinearLayout row;if(recycled instanceof LinearLayout)row=(LinearLayout)recycled;else{row=new LinearLayout(YouTubeFavoritesActivity.this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(Ui.dp(YouTubeFavoritesActivity.this,14),Ui.dp(YouTubeFavoritesActivity.this,12),Ui.dp(YouTubeFavoritesActivity.this,14),Ui.dp(YouTubeFavoritesActivity.this,12));TextView title=Ui.text(YouTubeFavoritesActivity.this,"",17,Ui.TEXT);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);row.addView(title);TextView detail=Ui.text(YouTubeFavoritesActivity.this,"",12,Ui.MUTED);detail.setMaxLines(2);detail.setEllipsize(TextUtils.TruncateAt.END);row.addView(detail);}YouTubeFavoritesData.Item item=shown.get(i);((TextView)row.getChildAt(0)).setTextColor(Ui.TEXT);((TextView)row.getChildAt(1)).setTextColor(Ui.MUTED);((TextView)row.getChildAt(0)).setText(item.title);((TextView)row.getChildAt(1)).setText((item.url.contains("/playlist?")?"Playlist":"Vídeo")+" • "+item.url);Ui.card(row,false);row.setContentDescription("Abrir favorito do YouTube: "+item.title);return row;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,i,id)->open(shown.get(i)));list.setOnItemLongClickListener((p,v,i,id)->{options(shown.get(i));return true;});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));TextView note=Ui.text(this,"Salvos neste celular, separados das músicas favoritas. Não sincroniza com a conta Google nem integra o backup de músicas atual. Abrir o conteúdo requer internet. Segure um item para renomear, remover ou consultar formatos.",12,Ui.MUTED);root.addView(note);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){render();}public void afterTextChanged(Editable e){}});if(state!=null)search.setText(state.getString("query",""));}
 private void render(){if(adapter==null)return;YouTubeFavoritesData data=YouTubeFavorites.read(this);SearchText.Query term=SearchText.prepare(search.getText().toString());shown.clear();for(YouTubeFavoritesData.Item item:data.items)if(term.matches(item.title+" "+item.url))shown.add(item);adapter.notifyDataSetChanged();status.setText(!data.writable?"Os favoritos têm formato desconhecido ou dados inválidos e foram preservados sem alteração.":data.items.isEmpty()?"Nenhum favorito. Abra um vídeo ou playlist e toque em Favoritar.":shown.size()+" de "+data.items.size()+" favoritos • limite de "+YouTubeFavoritesData.MAX);}
 private void open(YouTubeFavoritesData.Item item){if(opening)return;opening=true;startActivity(new Intent(this,YouTubeActivity.class).putExtra(YouTubeFavorites.EXTRA,item.url).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 private void options(YouTubeFavoritesData.Item item){if(optionsDialog!=null)optionsDialog.dismiss();optionsDialog=new AlertDialog.Builder(this).setTitle(item.title).setItems(new String[]{"Renomear","Remover dos favoritos","Ver formatos para baixar"},(d,n)->{if(n==0)rename(item);else if(n==1){YouTubeFavorites.remove(this,item.url);render();}else startActivity(new Intent(this,DownloadsActivity.class).putExtra("analyze_link",item.url).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));}).setNegativeButton("Fechar",null).show();}
 private void rename(YouTubeFavoritesData.Item item){EditText input=new EditText(this);input.setSingleLine(true);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(160)});input.setText(item.title);input.setContentDescription("Nome do favorito do YouTube");editDialog=new AlertDialog.Builder(this).setTitle("Renomear favorito").setView(input).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();editDialog.setOnShowListener(d->editDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(YouTubeFavoritesData.title(input.getText().toString()).isEmpty()){input.setError("Digite um nome");return;}if(YouTubeFavorites.read(this).find(item.url)==null){editDialog.dismiss();render();return;}if(!YouTubeFavorites.save(this,item.url,input.getText().toString())){input.setError("Não foi possível salvar; os dados foram preservados");return;}editDialog.dismiss();render();}));editDialog.show();}
 @Override protected void onResume(){super.onResume();render();}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("query",search.getText().toString());super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(optionsDialog!=null)optionsDialog.dismiss();if(editDialog!=null)editDialog.dismiss();super.onDestroy();}
}
